import {
  DataTable,
  DataTableContent,
  DataTablePagination,
  DataTableToolbar,
  DataTableViewOptions,
  DataTableSelectionBar,
  useDataTable,
  ColumnDef,
} from "@traxion-global/design-system/react";

const tableState = useDataTable<User>();

// Access selected rows — full row data, persists across pages
const selected = Object.values(tableState.selectedRows);
const selectedIds = Object.keys(tableState.selectedRows);

<DataTable
  columns={columns}
  data={data}
  pageCount={pageCount}
  enableRowSelection
  rowSelectionKey={(row) => String(row.id)}
  {...tableState}
>
  <DataTableToolbar>
    {selectedIds.length > 0 && (
      <Button onClick={() => handleBulkDelete(selectedIds)}>
        Delete ({selectedIds.length})
      </Button>
    )}
  </DataTableToolbar>
  <DataTableContent />
  <DataTablePagination />
</DataTable>

const router = useRouter();
const searchParams = useSearchParams();

const tableState = useDataTable({
  router,
  searchParams,
  namespace: "users",
});

// Default text editor — edits in place (no form chrome)
{ header: "Name", accessorKey: "firstName", enableEditing: true }

// Custom editor via editCell (e.g. a Select). Style the control to blend into
// the cell using the inline recipe on the trigger className.
{
  header: "Role",
  accessorKey: "role",
  enableEditing: true,
  editCell: ({ value, stage, cancel }) => (
    <Select
      defaultOpen
      value={value as string}
      onValueChange={(v) => stage(v)}
      onOpenChange={(open) => { if (!open) cancel(); }}
    >
      <SelectTrigger className="h-auto border-0 px-0 py-0 shadow-none focus:ring-0">
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        <SelectItem value="admin">admin</SelectItem>
        <SelectItem value="user">user</SelectItem>
      </SelectContent>
    </Select>
  ),
}

const [data, setData] = useState<User[]>([]);
const [cellErrors, setCellErrors] = useState<Record<string, Record<string, string>>>({});

const handleCellsEdited = async ({ data: nextData, changes }: CellsEditedPayload<User>) => {
  const errors = validate(nextData); // your validation
  if (Object.keys(errors).length > 0) {
    setCellErrors(errors);
    return Promise.reject(new Error("invalid")); // keep pending edits
  }
  setData(nextData);          // optimistic local update
  // persist `changes` to your API here (PATCH only what changed)
  setCellErrors({});
};

<DataTable
  columns={columns}
  data={data}
  pageCount={pageCount}
  {...tableState}
  enableCellEditing
  rowSelectionKey={(row) => String(row.id)}
  onCellsEdited={handleCellsEdited}
  onDiscardEdits={() => setCellErrors({})}
  cellErrors={cellErrors}
>
  <DataTableContent />
  <DataTablePagination />
  <DataTableEditBar />
</DataTable>

const columns: ColumnDef<User>[] = [
  // Left edge — identity / selection stays in view
  { id: "select", header: ({ table }) => <Checkbox ... />, size: 50, pin: "left" },
  { accessorKey: "id", header: "ID", size: 50, pin: "left" },
  // Center — scrolls horizontally
  { accessorKey: "firstName", header: "Name" },
  { accessorKey: "email", header: "Email" },
  { accessorKey: "company.name", header: "Company" },
  // Right edge — actions stay accessible
  { id: "actions", header: () => <span className="sr-only">Actions</span>, size: 120, pin: "right" },
];

// Pinning is meaningful only when the table overflows its container. Give
// columns enough width (TanStack `size`, default 150px) that the total exceeds
// the container; truncate long text per-column with a `truncate` cell so columns
// keep their width:
{
  accessorKey: "email",
  header: "Email",
  cell: ({ row }) => (
    <div className="truncate" title={row.original.email}>{row.original.email}</div>
  ),
}

// Simple non-sortable column — default, no sort button rendered
{ header: "Name", accessorKey: "firstName" }

// Fixed-width non-sortable column
{ header: "ID", accessorKey: "id", size: 50 }

// Sortable column — add enableSorting: true, table auto-renders sort button
{ header: "Email", accessorKey: "email", enableSorting: true }

// Non-sortable column (default, explicit for clarity)
{ header: "Company", accessorKey: "company.name", enableSorting: false }

// Custom cell renderer — string header still gets sort button automatically
{
  id: "firstName",
  header: "User",
  accessorKey: "firstName",
  cell: ({ row }) => (
    <div className="flex items-center gap-2">
      <User className="h-4 w-4 text-muted-foreground" />
      <span>{row.original.firstName} {row.original.lastName}</span>
    </div>
  ),
}

// Action buttons column (non-sortable, non-hideable, render function header)
{
  id: "actions",
  header: () => <div className="text-right">Actions</div>,
  size: 100,
  enableSorting: false,
  enableHiding: false,
  cell: ({ row }) => (
    <div className="flex gap-2 justify-end">
      <Button size="icon" variant="outline" onClick={() => handleEdit(row.original.id)}>
        <Pencil className="h-4 w-4" />
      </Button>
    </div>
  ),
}

// Row selection checkbox column (render function header)
{
  id: "select",
  header: ({ table }) => (
    <Checkbox
      checked={
        table.getIsAllPageRowsSelected() ||
        (table.getIsSomePageRowsSelected() && "indeterminate")
      }
      onCheckedChange={(value) => table.toggleAllPageRowsSelected(!!value)}
      aria-label="Select all"
    />
  ),
  cell: ({ row }) => (
    <Checkbox
      checked={row.getIsSelected()}
      onCheckedChange={(value) => row.toggleSelected(!!value)}
      aria-label="Select row"
    />
  ),
  enableSorting: false,
  enableHiding: false,
  size: 50,
}

// Nested object accessor — use id matching the API field name for sorting/filtering
{
  id: "company.name",
  accessorKey: "company.name",
  header: "Company",
  enableSorting: false,
}

// Multi-line cell for related data
{
  id: "address.city",
  accessorKey: "address.city",
  header: "Location",
  enableSorting: false,
  cell: ({ row }) => (
    <div className="flex flex-col">
      <span className="font-medium">{row.original.address.city}</span>
      <span className="text-xs text-muted-foreground">
        {row.original.address.state}, {row.original.address.country}
      </span>
    </div>
  ),
}

import {
  DateRangePicker,
} from "@traxion-global/design-system/react";
import type { DateRange } from "@traxion-global/design-system/react";
import { useState } from "react";

// State inside the component
const [dateRange, setDateRange] = useState<DateRange | undefined>(undefined);

// Inside DataTableToolbar — use DateRangePicker, never <input type="date"> or manual Calendar+Popover
<DateRangePicker
  value={dateRange}
  onChange={(range) => {
    setDateRange(range);
    tableState.setColumnFilters((prev) => {
      const without = prev.filter((f) => f.id !== "myDateColumn");
      return range?.from ? [...without, { id: "myDateColumn", value: range }] : without;
    });
  }}
  numberOfMonths={2}
  localeCode="es"
/>

import { TimePicker, Label } from "@traxion-global/design-system/react";
import { useState } from "react";

const [fromTime, setFromTime] = useState("");

<div className="flex items-center gap-2">
  <Label htmlFor="from-time">Desde</Label>
  <TimePicker
    id="from-time"
    value={fromTime}
    onChange={(e) => {
      setFromTime(e.target.value);
      tableState.setColumnFilters((prev) => {
        const without = prev.filter((f) => f.id !== "time");
        return e.target.value ? [...without, { id: "time", value: e.target.value }] : without;
      });
    }}
    className="w-32"
  />
</div>
